import{_ as e}from"./chunks/gnss-topic-echo.C1_-nlwO.js";import{_ as a,o,c as i,a5 as s}from"./chunks/framework.D47SInms.js";const b=JSON.parse('{"title":"GNSS · RTK (satellite positioning)","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/interface/gnss.md","filePath":"manual/interface/gnss.md","lastUpdated":1791600043000}'),d={name:"manual/interface/gnss.md"};function n(r,t,l,c,h,g){return o(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="gnss-·-rtk-satellite-positioning" tabindex="-1">GNSS · RTK (satellite positioning) <a class="header-anchor" href="#gnss-·-rtk-satellite-positioning" aria-label="Permalink to &quot;GNSS · RTK (satellite positioning)&quot;">​</a></h1><p>With a GNSS receiver attached, the robot passes satellite positioning data through <strong>as raw NMEA sentences</strong>. The robot&#39;s <code>GPS</code> program reads the sentences from the receiver and republishes them unchanged on a ROS 2 topic.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>GNSS needs <strong>robot software that includes the <code>GPS</code> program</strong> and a GNSS receiver. For receivers and the LTE/GPS module see <a href="/RBQ/nightly/manual/product-descriptions/accessories#wifi-lte-gps-module">Accessories</a>.</p></div></div><h2 id="topic" tabindex="-1">Topic <a class="header-anchor" href="#topic" aria-label="Permalink to &quot;Topic {#topic}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Topic</td><td><code>/rbq/gps/nmea</code></td></tr><tr><td>Type</td><td><a href="https://docs.ros.org/en/noetic/api/nmea_msgs/html/msg/Sentence.html" target="_blank" rel="noreferrer"><code>nmea_msgs/Sentence</code></a></td></tr><tr><td>Direction</td><td>Pub (robot → client)</td></tr></tbody></table><p>The message has just two fields.</p><table tabindex="0"><thead><tr><th>Field</th><th>Contents</th></tr></thead><tbody><tr><td><code>header.stamp</code></td><td>The time the robot <strong>read</strong> the sentence (not the UTC inside it)</td></tr><tr><td><code>header.frame_id</code></td><td><code>gps</code> — the receiver (antenna) frame</td></tr><tr><td><code>sentence</code></td><td>One raw NMEA 0183 line (starts with <code>$</code>, checksum included)</td></tr></tbody></table><p>Sentences are <strong>not processed</strong>. Parsing is left to the subscriber; NMEA is a standard format with parsers in most languages.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /rbq/gps/nmea</span></span></code></pre></div><figure style="text-align:center;margin:1rem 0;"><img src="'+e+'" alt="ros2 topic echo /rbq/gps/nmea output showing GNRMC, GNGGA and GNGST sentences" style="display:block;margin:0 auto;max-width:100%;height:auto;border-radius:6px;"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Live output — the three sentences arrive in sequence each cycle ]</figcaption></figure><h2 id="sentences" tabindex="-1">The three sentences <a class="header-anchor" href="#sentences" aria-label="Permalink to &quot;The three sentences {#sentences}&quot;">​</a></h2><p>Of everything the receiver emits, only these three types are published; the rest are dropped. The <code>GN</code> prefix means the fix combines several constellations (GPS, GLONASS, Galileo, BeiDou).</p><h3 id="gnrmc" tabindex="-1"><code>$GNRMC</code> — position, speed, time <a class="header-anchor" href="#gnrmc" aria-label="Permalink to &quot;`$GNRMC` — position, speed, time {#gnrmc}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$GNRMC,&lt;UTC time&gt;,&lt;status&gt;,&lt;latitude&gt;,&lt;N/S&gt;,&lt;longitude&gt;,&lt;E/W&gt;,&lt;speed&gt;,&lt;course&gt;,&lt;UTC date&gt;,&lt;magnetic variation&gt;,&lt;E/W&gt;,&lt;mode&gt;,&lt;nav status&gt;*&lt;checksum&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Contents</th></tr></thead><tbody><tr><td>UTC time · date</td><td>When the fix was taken</td></tr><tr><td>Status</td><td>Data valid (<code>A</code>) or not (<code>V</code>)</td></tr><tr><td>Latitude · longitude</td><td>Position</td></tr><tr><td>Speed</td><td>Speed over ground (knots)</td></tr><tr><td>Course</td><td>Heading, relative to true north</td></tr><tr><td>Magnetic variation</td><td>Difference between true and magnetic north</td></tr><tr><td>Mode · nav status</td><td>How the position was determined, and the navigation status</td></tr></tbody></table><h3 id="gngga" tabindex="-1"><code>$GNGGA</code> — fix quality and altitude <a class="header-anchor" href="#gngga" aria-label="Permalink to &quot;`$GNGGA` — fix quality and altitude {#gngga}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$GNGGA,&lt;UTC time&gt;,&lt;latitude&gt;,&lt;N/S&gt;,&lt;longitude&gt;,&lt;E/W&gt;,&lt;fix quality&gt;,&lt;satellites&gt;,&lt;HDOP&gt;,&lt;altitude&gt;,M,&lt;geoid separation&gt;,M,&lt;DGPS age&gt;,&lt;station ID&gt;*&lt;checksum&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Contents</th></tr></thead><tbody><tr><td>Fix quality</td><td><strong>This is where you check the RTK state</strong> — see the table below</td></tr><tr><td>Satellites</td><td>Number of satellites used for the fix</td></tr><tr><td>HDOP</td><td>Horizontal dilution of precision — lower is better</td></tr><tr><td>Altitude</td><td>Above mean sea level</td></tr><tr><td>Geoid separation</td><td>Difference between the ellipsoid and the geoid</td></tr><tr><td>DGPS age · station ID</td><td>How long since the last correction (RTCM) and which base station sent it</td></tr></tbody></table><p>The fix-quality values are NMEA 0183 standard.</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>No fix</td></tr><tr><td><code>1</code></td><td>Standalone GPS fix</td></tr><tr><td><code>2</code></td><td>DGPS — corrections applied</td></tr><tr><td><code>4</code></td><td><strong>RTK fixed</strong> — integer ambiguities resolved, the most accurate</td></tr><tr><td><code>5</code></td><td><strong>RTK float</strong> — ambiguities not resolved</td></tr></tbody></table><h3 id="gngst" tabindex="-1"><code>$GNGST</code> — position error estimates <a class="header-anchor" href="#gngst" aria-label="Permalink to &quot;`$GNGST` — position error estimates {#gngst}&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$GNGST,&lt;UTC time&gt;,&lt;RMS&gt;,&lt;semi-major σ&gt;,&lt;semi-minor σ&gt;,&lt;orientation&gt;,&lt;latitude σ&gt;,&lt;longitude σ&gt;,&lt;altitude σ&gt;*&lt;checksum&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Contents</th></tr></thead><tbody><tr><td>RMS</td><td>RMS of the range residuals</td></tr><tr><td>Semi-major · semi-minor σ · orientation</td><td>Standard deviations and bearing of the error ellipse</td></tr><tr><td>Latitude · longitude · altitude σ</td><td>Per-axis position error standard deviation (m)</td></tr></tbody></table><p><strong>This sentence is how you judge what RTK actually bought you.</strong> Once the latitude and longitude σ drop to centimetre level, RTK has locked in.</p><h2 id="verify" tabindex="-1">Checking that it works <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Checking that it works {#verify}&quot;">​</a></h2><ol><li><strong>Is the topic flowing?</strong> — run <code>ros2 topic echo /rbq/gps/nmea</code> and watch for sentences.</li><li><strong>Is there a fix?</strong> — a fix quality of <code>0</code> in <code>$GNGGA</code> means no satellites yet. Move somewhere with open sky and wait a moment.</li><li><strong>Is RTK locked?</strong> — check that the fix quality is <code>4</code> (fixed) or <code>5</code> (float), and that the latitude and longitude σ in <code>$GNGST</code> are small enough.</li></ol><p>In <strong><a href="/RBQ/nightly/manual/gui/logs.html#real-time">Logs → Real Time</a></strong>, filtering down to the <code>GPS</code> process shows the connect and disconnect messages directly.</p><h2 id="troubleshooting" tabindex="-1">When it does not work <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;When it does not work {#troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause and fix</th></tr></thead><tbody><tr><td>Nothing arrives on the topic</td><td>Check that the receiver is attached and powered, and that the robot can reach its address</td></tr><tr><td>It connects but no sentences appear</td><td>Anything outside <code>GNRMC</code>, <code>GNGGA</code> and <code>GNGST</code> is dropped. Enable those sentences in the receiver&#39;s own configuration</td></tr><tr><td>Fix quality never rises above <code>1</code></td><td>No corrections (RTCM) are arriving. Check the DGPS age and station ID in <code>$GNGGA</code></td></tr><tr><td>No fix indoors</td><td>GNSS needs a view of the sky. Indoors or between tall buildings there may be no fix, or a large error</td></tr></tbody></table><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck {#still-stuck}&quot;">​</a></h2><p>Tell us the receiver model and a few lines of <code>ros2 topic echo /rbq/gps/nmea</code> output.</p><p><strong>→ <a href="/RBQ/nightly/manual/support/">Support</a></strong></p>',32)])])}const m=a(d,[["render",n]]);export{b as __pageData,m as default};
